    instance.views.registerView({
      id: "side-panel.canvas",
      title: "Canvas",
      body: {
        kind: "react",
        render: () => <Text p="md">Open the Side Panel to edit the object name.</Text>,
      },
    });
    instance.views.registerView({
      id: "side-panel.inspector",
      title: "Inspector",
