        kind: "react",
        render: () => (
          <Stack p="md" gap="sm">
            <Text>Object name</Text>
            <Input aria-label="Object name" defaultValue="Clay Study" />
          </Stack>
        ),
      },
    });
    instance.shellPlacements.registerPlacement({
      id: "side-panel.canvas",
      item: {
        kind: "view",
        presence: "fixed",
        view: {
          kind: "view",
          id: "side-panel.canvas",
        },
      },
      region: "main",
    });
    instance.shellPlacements.registerPlacement({
      id: "side-panel.inspector",
      item: {
        kind: "view",
        presence: "fixed",
        view: {
          kind: "view",
          id: "side-panel.inspector",
        },
      },
      region: "side",
    });
