      if (scope === 0) {
        await Promise.resolve();
        publish(sections);
        setStarted(1);
        await new Promise<void>((resolve) => signal.addEventListener("abort", () => resolve(), { once: true }));
      } else {
        setStarted(2);
        signal.addEventListener("abort", () => pending.resolve(), { once: true });
